# Strategy variants: NAME|definitions (separated by ' ;; ')
# Baselines
base-main|idpv1=First(IDPtoQDP[Apply = CONSTONLY]:RunDefaultStrategyForObligation, First(Solve(Timer(12000, idpFast)), AnyDelay(5000, Solve(idpSlow), Solve(IDPtoQDP[Apply = ALWAYSFILTER]:RunDefaultStrategyForObligation))))
base-current|
# Single conversions (the rest of idpv1 is not run)
qdp-constonly|idpv1=Solve(IDPtoQDP[Apply = CONSTONLY]:RunDefaultStrategyForObligation)
qdp-encode|idpv1=Solve(IDPtoQDP:RunDefaultStrategyForObligation)
qdp-encode-filter|idpv1=Solve(IDPtoQDP[Apply = ALWAYSFILTER]:RunDefaultStrategyForObligation)
qdp-remove|idpv1=Solve(IDPtoQDP[Ints=REMOVE]:RunDefaultStrategyForObligation)
qdp-remove-filter|idpv1=Solve(IDPtoQDP[Ints=REMOVE, Apply=ALWAYSFILTER]:RunDefaultStrategyForObligation)
irs-intonly|idpv1=Solve(IDPtoIRS[Apply=INTONLY]:RunDefaultStrategyForObligation)
irs|idpv1=Solve(IDPtoIRS:RunDefaultStrategyForObligation)
# IDP processors only
idp-fast|idpv1=Solve(idpFast)
idp-slow|idpv1=Solve(idpSlow)
# Temporary filters in front of idpSlow
irstemp-slow|idpv1=Solve(Maybe(IDPtoIRS[TempFilter=True, Time=10000, Strategy="idpIRSRuleRemoval"]):idpSlow)
qdptemp-slow|idpv1=Solve(Maybe(IDPtoQDP[Ints=REMOVE, TempFilter=True, Time=10000, Strategy="idpQDPRuleRemoval"]):idpSlow)
# ===== Combinations (based on the current idpv1) =====
# without the QDP encoding (ALWAYSFILTER), which is expensive and only proves choice.itrs
cur-noenc|idpv1MainLoop=First(IDPtoQDP[Apply = CONSTONLY]:RunDefaultStrategyForObligation, First(Solve(Timer(12000, idpFast)), Any(Solve(idpSlow), Solve(IDPtoIRS[TempFilter=True, Time=10000, Strategy="idpIRSRuleRemoval"]:idpv1MainLoop), Solve(IDPtoQDP[Ints=REMOVE, TempFilter=True, Time=10000, Strategy="idpQDPRuleRemoval"]:idpv1MainLoop)))) ;; idpNonInfSlow=AnyDelay(10000, Any(idpNonInfIntSlow, idpNonInfIntShapedLR, idpNonInfIntShapedLL), idpNonInfIntVerySlow)
# QDP encoding only once, after 15 s
cur-lateenc|idpv1MainLoop=First(IDPtoQDP[Apply = CONSTONLY]:RunDefaultStrategyForObligation, First(Solve(Timer(12000, idpFast)), Any(Solve(idpSlow), Solve(IDPtoIRS[TempFilter=True, Time=10000, Strategy="idpIRSRuleRemoval"]:idpv1MainLoop), Solve(IDPtoQDP[Ints=REMOVE, TempFilter=True, Time=10000, Strategy="idpQDPRuleRemoval"]:idpv1MainLoop), Delay(15000, Solve(IDPtoQDP[Apply = ALWAYSFILTER]:RunDefaultStrategyForObligation))))) ;; idpNonInfSlow=AnyDelay(10000, Any(idpNonInfIntSlow, idpNonInfIntShapedLR, idpNonInfIntShapedLL), idpNonInfIntVerySlow)
# without the blocking idpFast stage (idpSlow contains idpNonInfFast anyway)
cur-nofast|idpv1MainLoop=First(IDPtoQDP[Apply = CONSTONLY]:RunDefaultStrategyForObligation, Any(Solve(idpSlow), Solve(IDPtoIRS[TempFilter=True, Time=10000, Strategy="idpIRSRuleRemoval"]:idpv1MainLoop), Solve(IDPtoQDP[Ints=REMOVE, TempFilter=True, Time=10000, Strategy="idpQDPRuleRemoval"]:idpv1MainLoop), Solve(IDPtoQDP[Apply = ALWAYSFILTER]:RunDefaultStrategyForObligation)))
# flat: CONSTONLY first, then everything in parallel; encoding late; filters recurse into the loop
flat|idpv1=First(IDPtoQDP[Apply = CONSTONLY]:RunDefaultStrategyForObligation, Any(Solve(IDPtoIRS:RunDefaultStrategyForObligation), Solve(IDPtoQDP[Ints=REMOVE]:RunDefaultStrategyForObligation), idpv1Loop)) ;; idpv1Loop=Any(Solve(idpSlow), Solve(IDPtoIRS[TempFilter=True, Time=10000, Strategy="idpIRSRuleRemoval"]:idpv1Loop), Solve(IDPtoQDP[Ints=REMOVE, TempFilter=True, Time=10000, Strategy="idpQDPRuleRemoval"]:idpv1Loop), Delay(15000, Solve(IDPtoQDP[Apply = ALWAYSFILTER]:RunDefaultStrategyForObligation))) ;; idpNonInfSlow=AnyDelay(10000, Any(idpNonInfIntSlow, idpNonInfIntShapedLR, idpNonInfIntShapedLL), idpNonInfIntVerySlow)
# flat, but the filters recurse into the full idpv1 (IRS and REMOVE again on the smaller IDP)
flat-rec|idpv1=First(IDPtoQDP[Apply = CONSTONLY]:RunDefaultStrategyForObligation, Any(Solve(IDPtoIRS:RunDefaultStrategyForObligation), Solve(IDPtoQDP[Ints=REMOVE]:RunDefaultStrategyForObligation), idpv1Loop)) ;; idpv1Loop=Any(Solve(idpSlow), Solve(IDPtoIRS[TempFilter=True, Time=10000, Strategy="idpIRSRuleRemoval"]:idpv1), Solve(IDPtoQDP[Ints=REMOVE, TempFilter=True, Time=10000, Strategy="idpQDPRuleRemoval"]:idpv1), Delay(15000, Solve(IDPtoQDP[Apply = ALWAYSFILTER]:RunDefaultStrategyForObligation))) ;; idpNonInfSlow=AnyDelay(10000, Any(idpNonInfIntSlow, idpNonInfIntShapedLR, idpNonInfIntShapedLL), idpNonInfIntVerySlow)
# ===== Prepared for round 2 (not run yet) =====
cur-enconce|idpNonInfSlow=AnyDelay(10000, Any(idpNonInfIntSlow, idpNonInfIntShapedLR, idpNonInfIntShapedLL), idpNonInfIntVerySlow)
cur-fast6|idpv1MainLoop=First(IDPtoQDP[Apply = CONSTONLY]:RunDefaultStrategyForObligation, First(Solve(Timer(6000, idpFast)), Any(Solve(idpSlow), Solve(IDPtoIRS[TempFilter=True, Time=10000, Strategy="idpIRSRuleRemoval"]:idpv1MainLoop), Solve(IDPtoQDP[Ints=REMOVE, TempFilter=True, Time=10000, Strategy="idpQDPRuleRemoval"]:idpv1MainLoop), Solve(IDPtoQDP[Apply = ALWAYSFILTER]:RunDefaultStrategyForObligation))))
cur-enconce-fast6|idpNonInfSlow=AnyDelay(10000, Any(idpNonInfIntSlow, idpNonInfIntShapedLR, idpNonInfIntShapedLL), idpNonInfIntVerySlow) ;; idpv1MainLoop=First(IDPtoQDP[Apply = CONSTONLY]:RunDefaultStrategyForObligation, First(Solve(Timer(6000, idpFast)), Any(Solve(idpSlow), Solve(IDPtoIRS[TempFilter=True, Time=10000, Strategy="idpIRSRuleRemoval"]:idpv1MainLoop), Solve(IDPtoQDP[Ints=REMOVE, TempFilter=True, Time=10000, Strategy="idpQDPRuleRemoval"]:idpv1MainLoop), Solve(IDPtoQDP[Apply = ALWAYSFILTER]:RunDefaultStrategyForObligation))))
base-current-r2|
# ===== Round 3: on top of cur-enconce-fast6 =====
r3-fast3|idpNonInfSlow=AnyDelay(10000, Any(idpNonInfIntSlow, idpNonInfIntShapedLR, idpNonInfIntShapedLL), idpNonInfIntVerySlow) ;; idpv1MainLoop=First(IDPtoQDP[Apply = CONSTONLY]:RunDefaultStrategyForObligation, First(Solve(Timer(3000, idpFast)), Any(Solve(idpSlow), Solve(IDPtoIRS[TempFilter=True, Time=10000, Strategy="idpIRSRuleRemoval"]:idpv1MainLoop), Solve(IDPtoQDP[Ints=REMOVE, TempFilter=True, Time=10000, Strategy="idpQDPRuleRemoval"]:idpv1MainLoop), Solve(IDPtoQDP[Apply = ALWAYSFILTER]:RunDefaultStrategyForObligation))))
r3-irshead3|idpNonInfSlow=AnyDelay(10000, Any(idpNonInfIntSlow, idpNonInfIntShapedLR, idpNonInfIntShapedLL), idpNonInfIntVerySlow) ;; idpv1MainLoop=First(IDPtoQDP[Apply = CONSTONLY]:RunDefaultStrategyForObligation, First(Solve(Timer(6000, idpFast)), Any(Solve(idpSlow), Solve(IDPtoIRS[TempFilter=True, Time=10000, Strategy="idpIRSRuleRemoval"]:idpv1MainLoop), Solve(IDPtoQDP[Ints=REMOVE, TempFilter=True, Time=10000, Strategy="idpQDPRuleRemoval"]:idpv1MainLoop), Solve(IDPtoQDP[Apply = ALWAYSFILTER]:RunDefaultStrategyForObligation)))) ;; idpv1=AnyDelay(3000, Solve(IDPtoIRS:RunDefaultStrategyForObligation), Any(Solve(IDPtoQDP[Ints=REMOVE]:RunDefaultStrategyForObligation), idpv1MainLoop))
r3-irshead6|idpNonInfSlow=AnyDelay(10000, Any(idpNonInfIntSlow, idpNonInfIntShapedLR, idpNonInfIntShapedLL), idpNonInfIntVerySlow) ;; idpv1MainLoop=First(IDPtoQDP[Apply = CONSTONLY]:RunDefaultStrategyForObligation, First(Solve(Timer(6000, idpFast)), Any(Solve(idpSlow), Solve(IDPtoIRS[TempFilter=True, Time=10000, Strategy="idpIRSRuleRemoval"]:idpv1MainLoop), Solve(IDPtoQDP[Ints=REMOVE, TempFilter=True, Time=10000, Strategy="idpQDPRuleRemoval"]:idpv1MainLoop), Solve(IDPtoQDP[Apply = ALWAYSFILTER]:RunDefaultStrategyForObligation)))) ;; idpv1=AnyDelay(6000, Solve(IDPtoIRS:RunDefaultStrategyForObligation), Any(Solve(IDPtoQDP[Ints=REMOVE]:RunDefaultStrategyForObligation), idpv1MainLoop))
r3-bothhead3|idpNonInfSlow=AnyDelay(10000, Any(idpNonInfIntSlow, idpNonInfIntShapedLR, idpNonInfIntShapedLL), idpNonInfIntVerySlow) ;; idpv1MainLoop=First(IDPtoQDP[Apply = CONSTONLY]:RunDefaultStrategyForObligation, First(Solve(Timer(6000, idpFast)), Any(Solve(idpSlow), Solve(IDPtoIRS[TempFilter=True, Time=10000, Strategy="idpIRSRuleRemoval"]:idpv1MainLoop), Solve(IDPtoQDP[Ints=REMOVE, TempFilter=True, Time=10000, Strategy="idpQDPRuleRemoval"]:idpv1MainLoop), Solve(IDPtoQDP[Apply = ALWAYSFILTER]:RunDefaultStrategyForObligation)))) ;; idpv1=AnyDelay(3000, Any(Solve(IDPtoIRS:RunDefaultStrategyForObligation), Solve(IDPtoQDP[Ints=REMOVE]:RunDefaultStrategyForObligation)), idpv1MainLoop)
# ===== Round 4: head start variants =====
r4-irsslowhead6|idpNonInfSlow=AnyDelay(10000, Any(idpNonInfIntSlow, idpNonInfIntShapedLR, idpNonInfIntShapedLL), idpNonInfIntVerySlow) ;; idpv1MainLoop=First(IDPtoQDP[Apply = CONSTONLY]:RunDefaultStrategyForObligation, First(Solve(Timer(6000, idpFast)), Any(Solve(idpSlow), Solve(IDPtoIRS[TempFilter=True, Time=10000, Strategy="idpIRSRuleRemoval"]:idpv1MainLoop), Solve(IDPtoQDP[Ints=REMOVE, TempFilter=True, Time=10000, Strategy="idpQDPRuleRemoval"]:idpv1MainLoop), Solve(IDPtoQDP[Apply = ALWAYSFILTER]:RunDefaultStrategyForObligation)))) ;; idpv1=AnyDelay(6000, Any(Solve(IDPtoIRS:RunDefaultStrategyForObligation), Solve(idpSlow)), Any(Solve(IDPtoQDP[Ints=REMOVE]:RunDefaultStrategyForObligation), idpv1MainLoop))
r4-irsfasthead6|idpNonInfSlow=AnyDelay(10000, Any(idpNonInfIntSlow, idpNonInfIntShapedLR, idpNonInfIntShapedLL), idpNonInfIntVerySlow) ;; idpv1MainLoop=First(IDPtoQDP[Apply = CONSTONLY]:RunDefaultStrategyForObligation, First(Solve(Timer(6000, idpFast)), Any(Solve(idpSlow), Solve(IDPtoIRS[TempFilter=True, Time=10000, Strategy="idpIRSRuleRemoval"]:idpv1MainLoop), Solve(IDPtoQDP[Ints=REMOVE, TempFilter=True, Time=10000, Strategy="idpQDPRuleRemoval"]:idpv1MainLoop), Solve(IDPtoQDP[Apply = ALWAYSFILTER]:RunDefaultStrategyForObligation)))) ;; idpv1Rest=First(IDPtoQDP[Apply = CONSTONLY]:RunDefaultStrategyForObligation, Any(Solve(idpSlow), Solve(IDPtoIRS[TempFilter=True, Time=10000, Strategy="idpIRSRuleRemoval"]:idpv1MainLoop), Solve(IDPtoQDP[Ints=REMOVE, TempFilter=True, Time=10000, Strategy="idpQDPRuleRemoval"]:idpv1MainLoop), Solve(IDPtoQDP[Apply = ALWAYSFILTER]:RunDefaultStrategyForObligation))) ;; idpv1=AnyDelay(6000, Any(Solve(IDPtoIRS:RunDefaultStrategyForObligation), Solve(idpFast)), Any(Solve(IDPtoQDP[Ints=REMOVE]:RunDefaultStrategyForObligation), idpv1Rest))
